            this.students = Collections.unmodifiableList(new ArrayList<>(students));
        }
        public int getId() { return id; }
        public String getName() { return name; }
        public int getRoomNumber() { return roomNumber; }
        public List<Student> getStudents() { return students; }
    }

    public static final class Page {
        private final List<Room> items;
        private final int pageNumber, pageSize, totalMatches;
        private Page(List<Room> items, int pageNumber, int pageSize, int totalMatches) {
            this.items = Collections.unmodifiableList(new ArrayList<>(items));
            this.pageNumber = pageNumber; this.pageSize = pageSize; this.totalMatches = totalMatches;
        }
        public List<Room> getItems() { return items; }
        public int getPageNumber() { return pageNumber; }
        public int getPageSize() { return pageSize; }
        public int getTotalMatches() { return totalMatches; }
    }

    public static Page listRooms(List<Room> rooms, String namePrefix, int pageNumber, int pageSize) {
        validateRooms(rooms);
        if (pageNumber < 0 || pageSize <= 0) throw new IllegalArgumentException("Invalid page");
        List<Room> matches = new ArrayList<>();
        for (Room room : rooms) {
            if (namePrefix == null || (room.getName() != null && room.getName().startsWith(namePrefix))) {
                matches.add(room);
            }
        }
        long rawStart = (long) (pageNumber - 1) * pageSize;
        if (rawStart >= matches.size()) return new Page(Collections.<Room>emptyList(), pageNumber, pageSize, matches.size());
        int start = (int) rawStart;
        int end = (int) Math.min((long) matches.size(), rawStart + pageSize);
        return new Page(matches.subList(start, end), pageNumber, pageSize, matches.size());
    }

    public static Room findRoom(List<Room> rooms, int id, int roomNumber) {
        validateRooms(rooms);
        for (Room room : rooms) {
            if (room.getId() == id && room.getRoomNumber() == roomNumber) return room;
        }
        return null;
    }

    private static void validateRooms(List<Room> rooms) {
        if (rooms == null || rooms.contains(null)) throw new IllegalArgumentException("Invalid rooms");
    }
}

