import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    interface Action { void run(); }

    public static void main(String[] args) {
        List<Solution.Student> sourceStudents = new ArrayList<Solution.Student>();
        sourceStudents.add(new Solution.Student(1, "Ana"));
        Solution.Room alpha = new Solution.Room(10, "Alpha", 101, sourceStudents);
        sourceStudents.add(new Solution.Student(2, "Later"));
        eq(1, alpha.getStudents().size(), "Room must copy students");
        expectUnsupported(new Action() { public void run() {
            alpha.getStudents().add(new Solution.Student(3, "X"));
        }});

        Solution.Room alpine = new Solution.Room(11, "Alpine", 102,
                Arrays.asList(new Solution.Student(4, "Bo")));
        Solution.Room beta = new Solution.Room(12, "Beta", 103,
                new ArrayList<Solution.Student>());
        Solution.Room unnamed = new Solution.Room(13, null, 104,
                new ArrayList<Solution.Student>());
        List<Solution.Room> rooms = new ArrayList<Solution.Room>(Arrays.asList(beta, alpha, alpine, unnamed));

        Solution.Page first = Solution.listRooms(rooms, "Al", 0, 1);
        eq(0, first.getPageNumber(), "page number");
        eq(1, first.getPageSize(), "page size");
        eq(2, first.getTotalMatches(), "total matches");
        eq(1, first.getItems().size(), "first size");
        same(alpha, first.getItems().get(0), "input order");

        Solution.Page second = Solution.listRooms(rooms, "Al", 1, 1);
        same(alpine, second.getItems().get(0), "second page");
        Solution.Page beyond = Solution.listRooms(rooms, "Al", 9, 2);
        eq(0, beyond.getItems().size(), "beyond page");
        eq(2, beyond.getTotalMatches(), "beyond total");

        Solution.Page all = Solution.listRooms(rooms, null, 0, 20);
        eq(4, all.getTotalMatches(), "null prefix");
        same(beta, all.getItems().get(0), "all order");
        Solution.Page emptyPrefix = Solution.listRooms(rooms, "", 0, 20);
        eq(3, emptyPrefix.getTotalMatches(), "empty prefix excludes null name");

        Solution.Page hugePage = Solution.listRooms(rooms, null, Integer.MAX_VALUE, 2);
        eq(0, hugePage.getItems().size(), "pagination multiplication overflow");
        expectUnsupported(new Action() { public void run() { first.getItems().clear(); }});
        rooms.clear();
        eq(1, first.getItems().size(), "page must snapshot input");
        same(alpha, first.getItems().get(0), "snapshot item");

        List<Solution.Room> findList = new ArrayList<Solution.Room>();
        Solution.Room duplicate1 = new Solution.Room(8, "One", 88, new ArrayList<Solution.Student>());
        Solution.Room duplicate2 = new Solution.Room(8, "Two", 88, new ArrayList<Solution.Student>());
        findList.add(duplicate1);
        findList.add(duplicate2);
        same(duplicate1, Solution.findRoom(findList, 8, 88), "find first reference");
        check(Solution.findRoom(findList, 8, 89) == null, "find no match");
        eq(2, findList.size(), "find mutated list");

        expectIllegal(new Action() { public void run() { Solution.listRooms(null, null, 0, 1); }});
        expectIllegal(new Action() { public void run() { Solution.listRooms(new ArrayList<Solution.Room>(), null, -1, 1); }});
        expectIllegal(new Action() { public void run() { Solution.listRooms(new ArrayList<Solution.Room>(), null, 0, 0); }});
        expectIllegal(new Action() { public void run() {
            Solution.listRooms(Arrays.asList(alpha, null), null, 0, 1);
        }});
        expectIllegal(new Action() { public void run() { Solution.findRoom(null, 1, 1); }});
        expectIllegal(new Action() { public void run() { Solution.findRoom(Arrays.asList(alpha, null), 10, 101); }});
    }

    static void expectIllegal(Action action) {
        try { action.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }

    static void expectUnsupported(Action action) {
        try { action.run(); throw new AssertionError("expected UnsupportedOperationException"); }
        catch (UnsupportedOperationException expected) { }
    }

    static void same(Object expected, Object actual, String message) {
        if (expected != actual) throw new AssertionError(message);
    }

    static void eq(int expected, int actual, String message) {
        if (expected != actual) throw new AssertionError(message + ": expected " + expected + " but got " + actual);
    }

    static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

